  json: {
    ...$json,
    DIRECTUS_URL: DIRECTUS_URL.replace(/\/+$/, ""),
    DIRECTUS_TOKEN,
    DEEPSEEK_MODEL,
    DEEPSEEK_MAX_CHARS,
